    assert(solution.minDeletions("abcdefghijklmnopqrstuvwxyz") == vector<int>25);
    assert(solution.minDeletions("aabbccddeeffgghhiijjkkllmmnnooppqqrrssttuuvvwwxxyyzz") == vector<int>49);
    assert(solution.minDeletions("ceabaacb") == vector<int>2);
    assert(solution.minDeletions("zzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzz") == vector<int>0);
    assert(solution.minDeletions("aaabbbcc") == vector<int>2);
    assert(solution.minDeletions("aabbccddeeffgghhii") == vector<int>15);
    assert(solution.minDeletions("zyxwvutsrqponmlkjihgfedcba") == vector<int>25);
    assert(solution.minDeletions("a") == vector<int>0);
    assert(solution.minDeletions("zzzzzzzzzzyyyyyyyyyxxxxxxxwwwwwwvvvvuuuuutttttsssssrrrrqqqqppppooooonnnnmmmmlllkkkjjjiii") == vector<int>41);
    assert(solution.minDeletions("aabbccddeeefffggg") == vector<int>11);
    assert(solution.minDeletions("aabbccddeeefffhhhiiijjkkllmmnnooppqqrrssttuuvvwwxxyyzz") == vector<int>48);
    assert(solution.minDeletions("aabbccddeeffgghhiijjkkllmmnnooppqqrrssttuuvvwwxxyyzzzzzzzzzz") == vector<int>47);
    assert(solution.minDeletions("pppppppppooooooonnnnnmmmllllllkkkkjjjjiiiiiiiihhhhhhhggggggg") == vector<int>15);
    assert(solution.minDeletions("aabbbccccddddeeeee") == vector<int>3);
    assert(solution.minDeletions("abababababababababab") == vector<int>1);
    assert(solution.minDeletions("zzzzzzzzzzzyyyyyyyxxxxxxxwwwwwwvvvvuuuutttssrrqponmlkjihgfedcba") == vector<int>24);
    assert(solution.minDeletions("aabbbcccddddeeeeeffffffggggggghhhhhhhhiiiiiiiiijjjjjjjjjj") == vector<int>2);
